class ShedQueue {                       // capacity fixed, drop-oldest policy
    std::deque<Item> q_; std::mutex m_; std::condition_variable cv_; std::size_t cap_{1024};
public:
    bool try_push(Item it) {            // false => shed; the caller counts it
        std::lock_guard lk{m_};
        bool room = q_.size() < cap_;
        if (!room) q_.pop_front();
        q_.push_back(std::move(it)); cv_.notify_one(); return room; }
    Item pop() {
        std::unique_lock lk{m_}; cv_.wait(lk, [&]{ return !q_.empty(); });
        Item it = std::move(q_.front()); q_.pop_front(); return it; } };

